const body = $input.item.json.body || {};
const callerNumber = body.message?.call?.customer?.number || 'Unknown';

const assistantConfig = {
  assistant: {
    name: "PropBot AI",
    firstMessage: "Hi there! You've reached PropBot Realty's AI assistant. I can help you explore properties, check viewing availability, and book appointments. How can I help you today?",
    model: {
      provider: "openai",
      model: "gpt-4o",
      messages: [
        {
          role: "system",
          content: `You are PropBot, a warm and professional real estate AI voice assistant for PropBot Realty, Austin TX.

YOUR AVAILABLE LISTINGS:
- 123 Maple Street — 3 bed / 2 bath — $450,000 — Move-in ready
- 456 Oak Avenue   — 4 bed / 3 bath — $675,000 — Recently renovated  
- 789 Pine Road    — 2 bed / 1 bath — $320,000 / Rental $2,200/mo

TOOLS YOU CAN CALL:
1. checkPropertyAvailability(propertyAddress, preferredDate)
2. scheduleViewing(propertyAddress, viewingDate, viewingTime, callerName, callerPhone)
3. getLeadInfo(phoneNumber)

RULES:
- Be concise — responses under 35 words when possible
- Always confirm names and contact info before scheduling
- Use natural, conversational language; avoid sounding robotic
- If caller asks about something outside real estate, politely redirect
- End every successful booking with the confirmation number`
        }
      ],
      tools: [
        {
          type: "function",
          function: {
            name: "checkPropertyAvailability",
            description: "Check available viewing slots for a specific property",
            parameters: {
              type: "object",
              properties: {
                propertyAddress: { type: "string", description: "Full or partial property address" },
                preferredDate: { type: "string", description: "Caller's preferred date, e.g. this Saturday" }
              },
              required: ["propertyAddress"]
            }
          }
        },
        {
          type: "function",
          function: {
            name: "scheduleViewing",
            description: "Book a property viewing appointment for the caller",
            parameters: {
              type: "object",
              properties: {
                propertyAddress: { type: "string", description: "Property address to view" },
                viewingDate: { type: "string", description: "Date for the viewing" },
                viewingTime: { type: "string", description: "Time for the viewing" },
                callerName: { type: "string", description: "Full name of the caller" },
                callerPhone: { type: "string", description: "Callback phone number" }
              },
              required: ["propertyAddress", "viewingDate", "viewingTime", "callerName"]
            }
          }
        },
        {
          type: "function",
          function: {
            name: "getLeadInfo",
            description: "Look up existing lead profile by caller phone number",
            parameters: {
              type: "object",
              properties: {
                phoneNumber: { type: "string", description: "Caller phone number in E.164 format" }
              },
              required: ["phoneNumber"]
            }
          }
        }
      ]
    },
    voice: {
      provider: "11labs",
      voiceId: "jqcCZkN6Knx8BJ5TBdYR",
      stability: 0.5,
      similarityBoost: 0.75,
      style: 0,
      useSpeakerBoost: true
    },
    transcriber: {
      provider: "deepgram",
      model: "nova-2",
      language: "en-US",
      smartFormat: true
    },
    recordingEnabled: true,
    endCallFunctionEnabled: true,
    silenceTimeoutSeconds: 20,
    maxDurationSeconds: 600
  }
};

return { json: assistantConfig };

const body = $input.item.json.body || {};
const args = body.message?.functionCall?.parameters || {};
const toolCallId = body.message?.toolCalls?.[0]?.id || body.message?.functionCall?.id || '';
const propertyAddress = (args.propertyAddress || '').toLowerCase();
const preferredDate = args.preferredDate || 'this weekend';

// Mock CRM / calendar data
const slots = {
  'maple': {
    address: '123 Maple Street',
    available: ['Saturday 10:00 AM', 'Saturday 2:00 PM', 'Sunday 11:00 AM'],
    price: '$450,000',
    type: 'Sale'
  },
  'oak': {
    address: '456 Oak Avenue',
    available: ['Saturday 1:00 PM', 'Saturday 4:00 PM', 'Sunday 10:00 AM'],
    price: '$675,000',
    type: 'Sale'
  },
  'pine': {
    address: '789 Pine Road',
    available: ['Friday 5:00 PM', 'Saturday 9:00 AM', 'Sunday 3:00 PM'],
    price: '$2,200/mo',
    type: 'Rental'
  }
};

const key = Object.keys(slots).find(k => propertyAddress.includes(k));
const property = key ? slots[key] : null;

let result;
if (property) {
  result = `${property.address} (${property.type} – ${property.price}) has these available slots: ${property.available.join(', ')}. Which works for you?`;
} else {
  result = `I found the following open slots around ${preferredDate}: Saturday at 10 AM and 2 PM, and Sunday at 11 AM. Which time works best?`;
}

return {
  json: {
      results: [
        {
          toolCallId: toolCallId,
          result: result
        }
      ]
    }
  }
;

const body = $input.item.json.body || {};
const args = body.message?.functionCall?.parameters || {};
const toolCallId = 
  body.message.toolCallList?.[0]?.id ||        // VAPI tool call list format
  body.message.toolCallId ||                    // top-level in message
  body.functionCall.toolCallId ||               // inside functionCall
  body.toolCallId ||                       // top-level in body
  'unknown';
const { propertyAddress, viewingDate, viewingTime, callerName, callerPhone } = args;

// Generate a confirmation ID
const confirmationId = 'PB-' + Math.floor(10000 + Math.random() * 90000);
const agentName = 'Jessica Martinez';

// In production: write to Google Sheets / CRM / calendar here
const appointment = {
  confirmationId,
  property: propertyAddress,
  date: viewingDate,
  time: viewingTime,
  clientName: callerName,
  clientPhone: callerPhone || 'not provided',
  agent: agentName,
  bookedAt: new Date().toISOString()
};

const result = `Booked! Your viewing at ${propertyAddress} is confirmed for ${viewingDate} at ${viewingTime}. Confirmation number: ${confirmationId}. Our agent ${agentName} will meet you there. We'll send a reminder to ${callerPhone || 'you'}. Is there anything else I can help with?`;

return {
  json: {
      results: [
        {
          toolCallId: toolCallId,
          result: result
        }
      ]
    }
  }
;

const body = $input.item.json.body || {};
const args = body.message?.functionCall?.parameters || {};
const phoneNumber = args.phoneNumber || '';
const toolCallId = 
  body.message.toolCallList?.[0]?.id ||        // VAPI tool call list format
  body.message.toolCallId ||                    // top-level in message
  body.functionCall.toolCallId ||               // inside functionCall
  body.toolCallId ||                       // top-level in body
  'unknown';
// Mock CRM lead database — replace with real DB/Sheets lookup in production
const leads = {
  '+15551234567': {
    name: 'Sarah Johnson',
    status: 'Active Buyer',
    budget: '$400K – $600K',
