    interests: 'Investment properties or rentals',
    lastContact: '1 week ago'
  },
  '+15554445555': {
    name: 'Priya Patel',
    status: 'Hot Lead',
    budget: '$600K+',
    interests: 'Luxury, renovated, large yard',
    lastContact: 'Yesterday'
  }
};

const lead = leads[phoneNumber];

