      results: [
        {
          toolCallId: toolCallId,
          result: result
        }
      ]
    }
  }
;

const body = $input.item.json.body || {};
const msg = body.message || {};

const callSummary = {
  callId: msg.call?.id || 'unknown',
  callType: msg.call?.type || 'unknown',
  callerNumber: msg.call?.customer?.number || 'unknown',
  durationSeconds: msg.durationSeconds || 0,
  endedReason: msg.endedReason || 'unknown',
  summary: msg.summary || 'No summary provided',
  recordingUrl: msg.recordingUrl || null,
  transcript: msg.transcript || '',
  transcriptLength: (msg.transcript || '').length,
  timestamp: new Date().toISOString(),
  status: 'logged'
};

// In production: write to Google Sheets, Airtable, or CRM here
console.log('[PropBot] Call ended:', JSON.stringify(callSummary, null, 2));

return { json: callSummary };

const body = $input.item.json.body || {};

// Extract lead data from the trigger payload
const leadName       = body.leadName        || 'Valued Customer';
const leadPhone      = body.phone           || '';
const propertyInterest = body.propertyInterest || 'properties in Austin TX';
const budget         = body.budget          || 'unspecified';
const agentNote      = body.agentNote       || '';

if (!leadPhone) {
  throw new Error('phone is required in the request body');
}

// Build Vapi outbound call payload
// IMPORTANT: Replace placeholder values with your real Vapi IDs before use
const vapiPayload = {
                    phoneNumberId: "YOUR_PHONE_NUMBER_ID",
  assistantId:"VAPI_ASSISTANT_ID",
  // ← Replace in Vapi dashboard
    // ← Replace with your Vapi assistant
  customer: {
    number: leadPhone,
    name: leadName
  },
  assistantOverrides: {
    firstMessage: `Hi ${leadName}! This is Alex from PropBot Realty calling. We noticed you were recently interested in ${propertyInterest}. I have a couple of exciting new listings that match your criteria — do you have about 2 minutes to hear about them?`,
    variableValues: {
      leadName,
      budget,
      propertyInterest,
      agentNote
    },
      model: {
      provider: "openai",
      model: "gpt-4o",
      messages: [
        {
          role: "system",
          content: `You are Alex, an outbound real estate sales assistant for PropBot Realty.

CALL GOAL: Qualify the lead, share relevant property options, and book a viewing or callback.

LEAD PROFILE:
- Name: ${leadName}
- Budget: ${budget}
- Interest: ${propertyInterest}
- Agent note: ${agentNote || 'None'}

AVAILABLE LISTINGS MATCHING LEAD:
- 123 Maple Street — 3 bed / 2 bath — $450,000
- 456 Oak Avenue   — 4 bed / 3 bath — $675,000
- 789 Pine Road    — 2 bed / 1 bath — Rental $2,200/mo

TOOLS: checkPropertyAvailability, scheduleViewing, getLeadInfo

RULES:
- Be friendly but respect their time — offer to call back if inconvenient
- Qualify budget and timeline in first 60 seconds
- Always get a concrete next step: viewing, callback, or email follow-up
- If they say not interested, note their reason and end politely`
        }
      ]
    }
  }
};

return { json: { vapiPayload, leadName, leadPhone } };

const vapiResponse = $input.item.json;

const response = {
  success: true,
  callId: vapiResponse.id || null,
  status: vapiResponse.status || 'queued',
  toNumber: vapiResponse.customer?.number || 'unknown',
  message: `Outbound call successfully initiated. Call ID: ${vapiResponse.id || 'pending'}`,
  timestamp: new Date().toISOString()
};

return { json: response };
